    # marks lying on it are the colored points to project perpendicularly.
    candidates = []
    for color, coords in points.items():
        for i, (r1, c1) in enumerate(coords):
            for r2, c2 in coords[i + 1:]:
                if abs(r2-r1) == abs(c2-c1) and (r1, c1) != (r2, c2):
                    candidates.append((abs(r2-r1), color, r1, c1, r2, c2))
    if not candidates:
        return [row[:] for row in grid]
    _, color, r1, c1, r2, c2 = max(candidates)

    out = [row[:] for row in grid]
    dr = 1 if r2 > r1 else -1
    dc = 1 if c2 > c1 else -1
    segment = []
    r, c = r1, c1
    while True:
        segment.append((r, c))
        if grid[r][c] == bg:
            out[r][c] = color
        if (r, c) == (r2, c2):
            break
        r += dr
        c += dc

    segset = set(segment)
    triggers = [(rr, cc, grid[rr][cc])
                for rr, cc in segment if grid[rr][cc] not in (bg, color)]
    for rr, cc, mark_color in triggers:
